CREATE OR REPLACE FUNCTION public.opc_query_before_entry_projection(p_actor_id uuid, p_draft_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
